/**
 * Enrol a new person.
 *
 * Route note: this file is `person/new.tsx` and sits beside `person/[id].tsx`.
 * expo-router resolves a static segment before a dynamic one, so `/person/new`
 * always reaches this screen. The only thing it costs is that a person whose
 * id were literally "new" would be unreachable -- ids are UUIDs generated by
 * the backend, so that cannot happen.
 *
 * On success the screen navigates to the new person's detail view rather than
 * back to the list. The reason is the next thing an administrator wants: the
 * person exists but has no enrolled face, and the detail screen is where that
 * state is shown and (from phase 3) fixed.
 */

import { useRouter } from 'expo-router';
import React, { useState } from 'react';
import { KeyboardAvoidingView, Platform, ScrollView, StyleSheet, View } from 'react-native';
import { Text, useTheme } from 'react-native-paper';

import { ApiError } from '../../src/api/client';
import type { PersonCreate } from '../../src/api/types';
import { useCameras } from '../../src/cameras/useCameras';
import {
  PersonForm,
  emptyPersonFormValues,
  type PersonFormValues,
} from '../../src/people/PersonForm';
import { roleNeedsCredentials } from '../../src/people/roles';
import { createPerson } from '../../src/people/usePeople';
import type { AppTheme } from '../../src/theme/theme';

export default function NewPersonScreen() {
  const theme = useTheme<AppTheme>();
  const router = useRouter();
  const cameras = useCameras();

  const [values, setValues] = useState<PersonFormValues>(emptyPersonFormValues());
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const submit = async () => {
    setSubmitting(true);
    setError(null);

    const email = values.email.trim();
    const payload: PersonCreate = {
      name: values.name.trim(),
      role: values.role,
      // An empty field is sent as null rather than "": the column is
      // nullable, and an empty string would occupy the unique index.
      email: email === '' ? null : email,
      allowed_cameras: values.allowedCameras,
    };
    // Only attached for roles that authenticate. The backend refuses a
    // password on a MONITORED person with 422, so sending one "just in case"
    // would turn a valid form into a rejected request.
    if (roleNeedsCredentials(values.role) && values.password) {
      payload.password = values.password;
    }

    try {
      const created = await createPerson(payload);
      router.replace(`/person/${created.id}`);
    } catch (caught) {
      setError(
        caught instanceof ApiError ? caught.message : 'The person could not be enrolled.',
      );
      setSubmitting(false);
    }
  };

  return (
    <KeyboardAvoidingView
      style={styles.screen}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView
        contentContainerStyle={[
          styles.content,
          { maxWidth: theme.maxContentWidth, alignSelf: 'center', width: '100%' },
        ]}
        keyboardShouldPersistTaps="handled"
      >
        <View style={styles.intro}>
          <Text variant="headlineSmall" style={styles.title}>
            Enrol a person
          </Text>
          <Text variant="bodyMedium" style={styles.subtitle}>
            Adding someone here makes them known to the hub. Their role decides whether they
            can also sign in to this application.
          </Text>
        </View>

        <PersonForm
          mode="create"
          values={values}
          onChange={setValues}
          originalRole={values.role}
          cameras={cameras.cameras}
          camerasLoading={cameras.loading}
          camerasError={cameras.error}
          submitting={submitting}
          error={error}
          submitLabel="Enrol person"
          onSubmit={() => void submit()}
        />
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
  },
  content: {
    padding: 16,
    paddingBottom: 48,
  },
  intro: {
    marginBottom: 16,
    gap: 4,
  },
  title: {
    fontWeight: '700',
  },
  subtitle: {
    opacity: 0.75,
  },
});
